// Command seed (re)creates the dummy databases used for development and tests.
//
// It only ever touches:
//   - MySQL databases `dbviewer_dummy` and `dbviewer_dummy_ro` (via the local socket)
//   - the `dbviewer_dummy` database inside the `dbviewer-pg` container (127.0.0.1:55432)
//   - testdata/dummy.sqlite and testdata/cache.sqlite
//
// Run it through testdata/seed.sh.
package main

import (
	"database/sql"
	"encoding/hex"
	"flag"
	"fmt"
	"math/rand/v2"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"

	"dbviewer/internal/model"
	"dbviewer/internal/store"

	_ "github.com/go-sql-driver/mysql"
	_ "github.com/jackc/pgx/v5/stdlib"
	_ "modernc.org/sqlite"
)

const (
	mysqlSocket = "/opt/workbench/data/run/mysqld/mysql84.sock"
	pgAdminDSN  = "postgres://postgres:dbviewer@127.0.0.1:55432/postgres?sslmode=disable"
	pgDummyDSN  = "postgres://postgres:dbviewer@127.0.0.1:55432/dbviewer_dummy?sslmode=disable"
)

// The only database names this program may drop/create.
var allowedMySQL = map[string]bool{"dbviewer_dummy": true, "dbviewer_dummy_ro": true}

func main() {
	dir := flag.String("dir", "testdata", "testdata directory (sqlite files are written here)")
	only := flag.String("only", "mysql,postgres,sqlite", "comma separated engines to seed")
	appdata := flag.Bool("appdata", true, "create testdata/appdata with sample projects/connections if it does not exist")
	flag.Parse()
	if *appdata {
		must(seedAppData(*dir))
	}

	engines := map[string]bool{}
	for _, e := range strings.Split(*only, ",") {
		engines[strings.TrimSpace(e)] = true
	}
	ds := generate()

	if engines["mysql"] {
		must(seedMySQL("dbviewer_dummy", ds, true))
		must(seedMySQL("dbviewer_dummy_ro", ds, false))
	}
	if engines["postgres"] {
		must(seedPostgres(ds))
	}
	if engines["sqlite"] {
		must(seedSQLite(filepath.Join(*dir, "dummy.sqlite"), ds))
		must(seedCache(filepath.Join(*dir, "cache.sqlite")))
	}
}

func must(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, "seed failed:", err)
		os.Exit(1)
	}
}

// ---------------------------------------------------------------------------
// Schema model

type col struct {
	name     string
	typ      string // pk, ref, int, smallint, bigint, dec, qty, float, bool, str:N, text, datetime, date, json, blob
	nullable bool
	def      string // raw SQL default (dialect independent subset)
}

type fk struct {
	cols     []string
	refTable string
	refCols  []string
}

type table struct {
	name    string
	cols    []col
	pk      []string // composite / explicit PK; empty + a "pk" column => that column
	noPK    bool
	uniques [][]string
	indexes [][]string
	fks     []fk
	rows    [][]any
	core    bool // part of the core (non filler) set
}

type num string   // decimal literal, rendered unquoted
type ts time.Time // datetime
type day time.Time

type dialect string

const (
	dMySQL  dialect = "mysql"
	dPG     dialect = "postgres"
	dSQLite dialect = "sqlite"
)

func (d dialect) q(id string) string {
	if d == dMySQL {
		return "`" + id + "`"
	}
	return `"` + id + `"`
}

func (d dialect) colType(c col) string {
	t := c.typ
	if strings.HasPrefix(t, "str:") {
		return "varchar(" + t[4:] + ")"
	}
	switch d {
	case dMySQL:
		switch t {
		case "pk":
			return "int unsigned NOT NULL AUTO_INCREMENT"
		case "ref":
			return "int unsigned"
		case "int":
			return "int"
		case "smallint":
			return "smallint"
		case "bigint":
			return "bigint"
		case "dec":
			return "decimal(20,4)"
		case "qty":
			return "decimal(12,4)"
		case "float":
			return "double"
		case "bool":
			return "tinyint(1)"
		case "text":
			return "text"
		case "datetime":
			return "datetime"
		case "date":
			return "date"
		case "json":
			return "json"
		case "blob":
			return "blob"
		}
	case dPG:
		switch t {
		case "pk":
			return "integer GENERATED BY DEFAULT AS IDENTITY"
		case "ref", "int":
			return "integer"
		case "smallint":
			return "smallint"
		case "bigint":
			return "bigint"
		case "dec":
			return "numeric(20,4)"
		case "qty":
			return "numeric(12,4)"
		case "float":
			return "double precision"
		case "bool":
			return "boolean"
		case "text":
			return "text"
		case "datetime":
			return "timestamp"
		case "date":
			return "date"
		case "json":
			return "jsonb"
		case "blob":
			return "bytea"
		}
	case dSQLite:
		switch t {
		case "pk", "ref", "int", "smallint", "bigint":
			return "INTEGER"
		case "dec":
			return "DECIMAL(20,4)"
		case "qty":
			return "DECIMAL(12,4)"
		case "float":
			return "REAL"
		case "bool":
			return "BOOLEAN"
		case "text":
			return "TEXT"
		case "datetime":
			return "DATETIME"
		case "date":
			return "DATE"
		case "json":
			return "JSON"
		case "blob":
			return "BLOB"
		}
	}
	panic("unknown type " + t)
}

func (t *table) pkCols() []string {
	if t.noPK {
		return nil
	}
	if len(t.pk) > 0 {
		return t.pk
	}
	for _, c := range t.cols {
		if c.typ == "pk" {
			return []string{c.name}
		}
	}
	return nil
}

func (d dialect) createTable(t *table, schema string) []string {
	name := d.q(t.name)
	if schema != "" {
		name = d.q(schema) + "." + d.q(t.name)
	}
	var parts []string
	pk := t.pkCols()
	for _, c := range t.cols {
		s := d.q(c.name) + " " + d.colType(c)
		if d == dSQLite && c.typ == "pk" && len(pk) == 1 {
			s += " PRIMARY KEY"
		} else if c.typ != "pk" || d == dPG {
			if c.nullable {
				s += " NULL"
			} else if c.typ != "pk" {
				s += " NOT NULL"
			}
		}
		if c.def != "" {
			s += " DEFAULT " + c.def
		}
		parts = append(parts, s)
	}
	if len(pk) > 0 && !(d == dSQLite && len(pk) == 1 && t.colByName(pk[0]).typ == "pk") {
		parts = append(parts, "PRIMARY KEY ("+d.list(pk)+")")
	}
	for _, u := range t.uniques {
		parts = append(parts, "UNIQUE ("+d.list(u)+")")
	}
	for _, f := range t.fks {
		ref := d.q(f.refTable)
		if schema != "" {
			ref = d.q(schema) + "." + ref
		}
		parts = append(parts, fmt.Sprintf("CONSTRAINT %s FOREIGN KEY (%s) REFERENCES %s (%s) ON DELETE CASCADE",
			d.q("fk_"+t.name+"_"+strings.Join(f.cols, "_")), d.list(f.cols), ref, d.list(f.refCols)))
	}
	stmts := []string{"CREATE TABLE " + name + " (\n  " + strings.Join(parts, ",\n  ") + "\n)"}
	for _, ix := range t.indexes {
		stmts = append(stmts, fmt.Sprintf("CREATE INDEX %s ON %s (%s)", d.q("ix_"+t.name+"_"+strings.Join(ix, "_")), name, d.list(ix)))
	}
	return stmts
}

func (t *table) colByName(n string) col {
	for _, c := range t.cols {
		if c.name == n {
			return c
		}
	}
	return col{}
}

func (d dialect) list(cols []string) string {
	out := make([]string, len(cols))
	for i, c := range cols {
		out[i] = d.q(c)
	}
	return strings.Join(out, ", ")
}

func (d dialect) lit(v any) string {
	switch x := v.(type) {
	case nil:
		return "NULL"
	case int:
		return strconv.Itoa(x)
	case int64:
		return strconv.FormatInt(x, 10)
	case float64:
		return strconv.FormatFloat(x, 'g', -1, 64)
	case num:
		return string(x)
	case bool:
		if d == dPG {
			if x {
				return "TRUE"
			}
			return "FALSE"
		}
		if x {
			return "1"
		}
		return "0"
	case ts:
		return "'" + time.Time(x).Format("2006-01-02 15:04:05") + "'"
	case day:
		return "'" + time.Time(x).Format("2006-01-02") + "'"
	case []byte:
		if d == dPG {
			return "'\\x" + hex.EncodeToString(x) + "'::bytea"
		}
		return "X'" + hex.EncodeToString(x) + "'"
	case string:
		s := strings.ReplaceAll(x, "'", "''")
		if d == dMySQL {
			s = strings.ReplaceAll(s, `\`, `\\`)
		}
		return "'" + s + "'"
	}
	panic(fmt.Sprintf("unsupported literal %T", v))
}

func (d dialect) inserts(t *table, schema string, batch int) []string {
	if len(t.rows) == 0 {
		return nil
	}
	name := d.q(t.name)
	if schema != "" {
		name = d.q(schema) + "." + d.q(t.name)
	}
	cols := make([]string, len(t.cols))
	for i, c := range t.cols {
		cols[i] = c.name
	}
	head := "INSERT INTO " + name + " (" + d.list(cols) + ") VALUES\n"
	var out []string
	for i := 0; i < len(t.rows); i += batch {
		end := min(i+batch, len(t.rows))
		var sb strings.Builder
		sb.WriteString(head)
		for j, r := range t.rows[i:end] {
			if j > 0 {
				sb.WriteString(",\n")
			}
			sb.WriteString("(")
			for k, v := range r {
				if k > 0 {
					sb.WriteString(", ")
				}
				sb.WriteString(d.lit(v))
			}
			sb.WriteString(")")
		}
		out = append(out, sb.String())
	}
	return out
}

