// Data generation

type dataset struct {
	tables []*table // in creation order (FK parents first)
	views  []string // view name -> defined per dialect in viewSQL
	stats  orderStats
}

type orderStats struct {
	daily map[string][2]float64 // day -> [orders, revenue]
	cust  map[int]*custStat
}

type custStat struct {
	orders      int
	ltv         float64
	first, last time.Time
}

var (
	firstNames = []string{"Jan", "Piet", "Klaas", "Sanne", "Emma", "Lucas", "Daan", "Julia", "Sophie", "Noah", "Liam", "Mila", "José", "Zoë", "Björn", "Åsa", "Chloé", "Mehmet", "Fatima", "Wei", "Søren", "Anouk", "Bram", "Lotte"}
	lastNames  = []string{"de Vries", "Jansen", "Bakker", "Visser", "Smit", "Meijer", "de Boer", "Mulder", "Müller", "Schmidt", "O'Brien", "Dubois", "Nguyen", "Yılmaz", "van Dijk", "Peters", "Hendriks", "van Leeuwen", "Dekker", "Brouwer"}
	domains    = []string{"example.com", "example.nl", "mail.test", "shop.test", "gmail.test", "outlook.test"}
	states     = []string{"new", "processing", "complete", "closed", "canceled", "holded"}
	statuses   = map[string]string{"new": "pending", "processing": "processing", "complete": "complete", "closed": "closed", "canceled": "canceled", "holded": "holded"}
	productAdj = []string{"Matte", "Chrome", "Brushed", "Black", "White", "Compact", "Deluxe", "Classic", "Modern", "Slim"}
	productN   = []string{"Faucet", "Shower head", "Sink", "Toilet seat", "Mirror cabinet", "Towel rail", "Bathtub", "Drain", "Thermostat valve", "Soap dispenser", "Basin", "Hand shower"}
	coupons    = []string{"WELCOME10", "SUMMER25", "FREESHIP", "BLACKFRIDAY", "VIP15"}
)

func generate() *dataset {
	r := rand.New(rand.NewPCG(42, 2024))
	ds := &dataset{stats: orderStats{daily: map[string][2]float64{}, cust: map[int]*custStat{}}}
	base := time.Date(2023, 1, 1, 8, 0, 0, 0, time.UTC)
	span := 3 * 365 * 24 * time.Hour
	randTime := func() time.Time {
		return base.Add(time.Duration(r.Int64N(int64(span)))).Truncate(time.Second)
	}
	money := func(lo, hi float64) (num, float64) {
		v := lo + r.Float64()*(hi-lo)
		v = float64(int64(v*100)) / 100
		return num(strconv.FormatFloat(v, 'f', 4, 64)), v
	}

	// store
	store := &table{name: "store", core: true, cols: []col{
		{name: "store_id", typ: "pk"}, {name: "code", typ: "str:32"}, {name: "website_id", typ: "smallint"},
		{name: "group_id", typ: "smallint"}, {name: "name", typ: "str:255"}, {name: "sort_order", typ: "smallint", def: "0"},
		{name: "is_active", typ: "bool"},
	}, uniques: [][]string{{"code"}}}
	for i, s := range [][2]string{{"default", "Default Store View"}, {"nl", "Nederlands"}, {"de", "Deutsch"}, {"be_fr", "Belgique (FR)"}} {
		store.rows = append(store.rows, []any{i + 1, s[0], 1, 1, s[1], i, i != 3})
	}

	// customer_entity
	cust := &table{name: "customer_entity", core: true, cols: []col{
		{name: "entity_id", typ: "pk"}, {name: "website_id", typ: "smallint", nullable: true}, {name: "email", typ: "str:255"},
		{name: "group_id", typ: "smallint", def: "1"}, {name: "store_id", typ: "ref", nullable: true},
		{name: "firstname", typ: "str:255"}, {name: "lastname", typ: "str:255"}, {name: "dob", typ: "date", nullable: true},
		{name: "gender", typ: "smallint", nullable: true}, {name: "is_active", typ: "bool"},
		{name: "created_at", typ: "datetime"}, {name: "updated_at", typ: "datetime"},
	}, uniques: [][]string{{"email", "website_id"}}, indexes: [][]string{{"lastname"}},
		fks: []fk{{cols: []string{"store_id"}, refTable: "store", refCols: []string{"store_id"}}}}
	type person struct{ first, last, email string }
	people := make([]person, 0, 600)
	for i := 1; i <= 600; i++ {
		fn, ln := firstNames[r.IntN(len(firstNames))], lastNames[r.IntN(len(lastNames))]
		email := fmt.Sprintf("%s.%s%d@%s", strings.ToLower(asciiOnly(fn)), strings.ToLower(strings.ReplaceAll(asciiOnly(ln), " ", "")), i, domains[r.IntN(len(domains))])
		people = append(people, person{fn, ln, email})
		var dob, gender any
		if r.IntN(3) > 0 {
			dob = day(time.Date(1950+r.IntN(55), time.Month(1+r.IntN(12)), 1+r.IntN(28), 0, 0, 0, 0, time.UTC))
		}
		if r.IntN(2) == 0 {
			gender = 1 + r.IntN(3)
		}
		created := randTime()
		cust.rows = append(cust.rows, []any{i, 1, email, 1 + r.IntN(3), 1 + r.IntN(3), fn, ln, dob, gender, r.IntN(20) > 0, ts(created), ts(created.Add(time.Duration(r.IntN(10000)) * time.Hour))})
	}

	// catalog_product_entity
	prod := &table{name: "catalog_product_entity", core: true, cols: []col{
		{name: "entity_id", typ: "pk"}, {name: "attribute_set_id", typ: "smallint", def: "4"}, {name: "type_id", typ: "str:32", def: "'simple'"},
		{name: "sku", typ: "str:64"}, {name: "has_options", typ: "bool"}, {name: "required_options", typ: "bool"},
		{name: "created_at", typ: "datetime"}, {name: "updated_at", typ: "datetime"},
	}, uniques: [][]string{{"sku"}}}
	type product struct {
		sku, name string
		price     float64
	}
	products := make([]product, 0, 300)
	for i := 1; i <= 300; i++ {
		name := productAdj[r.IntN(len(productAdj))] + " " + productN[r.IntN(len(productN))]
		sku := fmt.Sprintf("SKU-%05d", 10000+i*7)
		products = append(products, product{sku, name, 5 + r.Float64()*900})
		typ := "simple"
		if i%17 == 0 {
			typ = "configurable"
		}
		created := randTime()
		prod.rows = append(prod.rows, []any{i, 4, typ, sku, typ == "configurable", false, ts(created), ts(created.Add(48 * time.Hour))})
	}

	// catalog_product_entity_varchar (EAV)
	pvar := &table{name: "catalog_product_entity_varchar", core: true, cols: []col{
		{name: "value_id", typ: "pk"}, {name: "attribute_id", typ: "smallint"}, {name: "store_id", typ: "ref"},
		{name: "entity_id", typ: "ref"}, {name: "value", typ: "str:255", nullable: true},
	}, uniques: [][]string{{"entity_id", "attribute_id", "store_id"}}, indexes: [][]string{{"attribute_id"}},
		fks: []fk{
			{cols: []string{"entity_id"}, refTable: "catalog_product_entity", refCols: []string{"entity_id"}},
			{cols: []string{"store_id"}, refTable: "store", refCols: []string{"store_id"}},
		}}
	vid := 0
	for i, p := range products {
		vid++
		pvar.rows = append(pvar.rows, []any{vid, 73, 1, i + 1, p.name})
		vid++
		pvar.rows = append(pvar.rows, []any{vid, 121, 1, i + 1, strings.ToLower(strings.ReplaceAll(p.name, " ", "-")) + "-" + strconv.Itoa(i+1)})
		if i%2 == 0 {
			vid++
			pvar.rows = append(pvar.rows, []any{vid, 73, 2, i + 1, p.name + " (NL)"})
		}
		if i%9 == 0 {
			vid++
			pvar.rows = append(pvar.rows, []any{vid, 87, 1, i + 1, nil})
		}
	}

	// sales_order
	order := &table{name: "sales_order", core: true, cols: []col{
		{name: "entity_id", typ: "pk"}, {name: "increment_id", typ: "str:50"}, {name: "state", typ: "str:32"}, {name: "status", typ: "str:32"},
		{name: "store_id", typ: "ref"}, {name: "customer_id", typ: "ref", nullable: true}, {name: "customer_email", typ: "str:128"},
		{name: "customer_firstname", typ: "str:128", nullable: true}, {name: "customer_lastname", typ: "str:128", nullable: true},
		{name: "customer_is_guest", typ: "bool"}, {name: "grand_total", typ: "dec"}, {name: "subtotal", typ: "dec"},
		{name: "shipping_amount", typ: "dec", nullable: true}, {name: "tax_amount", typ: "dec"}, {name: "discount_amount", typ: "dec", def: "0"},
		{name: "total_qty_ordered", typ: "qty"}, {name: "weight", typ: "float", nullable: true}, {name: "base_currency_code", typ: "str:3"},
		{name: "coupon_code", typ: "str:255", nullable: true}, {name: "remote_ip", typ: "str:45", nullable: true},
		{name: "customer_note", typ: "text", nullable: true}, {name: "extra_data", typ: "json", nullable: true},
		{name: "payment_payload", typ: "blob", nullable: true},
		{name: "created_at", typ: "datetime"}, {name: "updated_at", typ: "datetime"},
	}, uniques: [][]string{{"increment_id", "store_id"}}, indexes: [][]string{{"customer_email"}, {"status"}, {"created_at"}},
		fks: []fk{
			{cols: []string{"store_id"}, refTable: "store", refCols: []string{"store_id"}},
			{cols: []string{"customer_id"}, refTable: "customer_entity", refCols: []string{"entity_id"}},
		}}
	item := &table{name: "sales_order_item", core: true, cols: []col{
		{name: "item_id", typ: "pk"}, {name: "order_id", typ: "ref"}, {name: "product_id", typ: "ref", nullable: true},
		{name: "sku", typ: "str:64"}, {name: "name", typ: "str:255", nullable: true}, {name: "qty_ordered", typ: "qty"},
		{name: "price", typ: "dec"}, {name: "row_total", typ: "dec"}, {name: "product_options", typ: "text", nullable: true},
		{name: "created_at", typ: "datetime"},
	}, indexes: [][]string{{"sku"}},
		fks: []fk{
			{cols: []string{"order_id"}, refTable: "sales_order", refCols: []string{"entity_id"}},
			{cols: []string{"product_id"}, refTable: "catalog_product_entity", refCols: []string{"entity_id"}},
		}}
	hist := &table{name: "sales_order_status_history", core: true, cols: []col{
		{name: "entity_id", typ: "pk"}, {name: "parent_id", typ: "ref"}, {name: "is_customer_notified", typ: "bool", nullable: true},
		{name: "comment", typ: "text", nullable: true}, {name: "status", typ: "str:32", nullable: true},
		{name: "entity_name", typ: "str:32", nullable: true}, {name: "created_at", typ: "datetime"},
	}, fks: []fk{{cols: []string{"parent_id"}, refTable: "sales_order", refCols: []string{"entity_id"}}}}
	grid := &table{name: "sales_order_grid", core: true, cols: []col{
		{name: "entity_id", typ: "pk"}, {name: "increment_id", typ: "str:50"}, {name: "status", typ: "str:32"},
		{name: "store_id", typ: "ref"}, {name: "customer_id", typ: "ref", nullable: true}, {name: "customer_email", typ: "str:128"},
		{name: "customer_name", typ: "str:255", nullable: true}, {name: "grand_total", typ: "dec"},
		{name: "payment_method", typ: "str:255", nullable: true}, {name: "created_at", typ: "datetime"},
	}, indexes: [][]string{{"customer_email"}, {"increment_id"}}}
	amasty := &table{name: "amasty_order_attribute_entity", core: true, cols: []col{
		{name: "entity_id", typ: "pk"}, {name: "parent_id", typ: "ref"}, {name: "parent_entity_type", typ: "smallint"},
	}, uniques: [][]string{{"parent_id", "parent_entity_type"}}}

	itemID, histID, amID := 0, 0, 0
	payments := []string{"checkmo", "ideal", "paypal_express", "klarna_pay_later", "banktransfer"}
	longNote := strings.Repeat("Lorem ipsum dolor sit amet, consectetur adipiscing elit. ", 200)
	for i := 1; i <= 2000; i++ {
		state := states[r.IntN(len(states))]
		storeID := 1 + r.IntN(3)
		var custID any
		var email, fn, ln string
		guest := r.IntN(10) < 3
		if guest {
			p := person{firstNames[r.IntN(len(firstNames))], lastNames[r.IntN(len(lastNames))], ""}
			p.email = fmt.Sprintf("guest%d@%s", i, domains[r.IntN(len(domains))])
			email, fn, ln = p.email, p.first, p.last
		} else {
			ci := r.IntN(len(people))
			custID = ci + 1
			email, fn, ln = people[ci].email, people[ci].first, people[ci].last
		}
		created := randTime()
		nItems := 1 + r.IntN(4)
		subtotal, qtyTotal := 0.0, 0.0
		for k := 0; k < nItems; k++ {
			itemID++
			pi := r.IntN(len(products))
			p := products[pi]
			qty := float64(1 + r.IntN(3))
			price := float64(int64(p.price*100)) / 100
			subtotal += price * qty
			qtyTotal += qty
			var opts any
			if r.IntN(3) == 0 {
				opts = fmt.Sprintf(`{"info_buyRequest":{"qty":%g,"product":%d},"options":[]}`, qty, pi+1)
			}
			var productID any = pi + 1
			if r.IntN(50) == 0 {
				productID = nil // product deleted
			}
			item.rows = append(item.rows, []any{itemID, i, productID, p.sku, p.name, num(fmt.Sprintf("%.4f", qty)), num(fmt.Sprintf("%.4f", price)), num(fmt.Sprintf("%.4f", price*qty)), opts, ts(created)})
		}
		var shipping any
		ship := 0.0
		if r.IntN(5) > 0 {
			ship = []float64{0, 4.95, 6.95, 12.5}[r.IntN(4)]
			shipping = num(fmt.Sprintf("%.4f", ship))
		}
		var coupon any
		discount := 0.0
		if r.IntN(8) == 0 {
			coupon = coupons[r.IntN(len(coupons))]
			discount = -float64(int64(subtotal*10)) / 100
		}
		tax := float64(int64(subtotal*21)) / 100
		grand := subtotal + ship + discount
		var note any
		switch r.IntN(12) {
		case 0:
			note = "Please deliver after 17:00.\nRing twice; the bell is broken."
		case 1:
			note = ""
		case 2:
			note = longNote
		case 3:
			note = `Customer says: "can't wait" \ it's a gift`
		}
		var extra any
		if r.IntN(2) == 0 {
			extra = fmt.Sprintf(`{"source": "%s", "utm": {"campaign": "c%d", "medium": "email"}, "gift_wrap": %t, "tags": ["a", "b"]}`,
				[]string{"web", "app", "pos"}[r.IntN(3)], r.IntN(20), r.IntN(4) == 0)
		}
		var payload any
		if r.IntN(6) == 0 {
			b := make([]byte, 16+r.IntN(48))
			for k := range b {
				b[k] = byte(r.IntN(256))
			}
			payload = b
		}
		var ip any
		if r.IntN(10) > 0 {
			ip = fmt.Sprintf("192.0.2.%d", r.IntN(255))
		}
		var weight any
		if r.IntN(4) > 0 {
			weight = float64(int64(r.Float64()*4000)) / 100
		}
		inc := fmt.Sprintf("%09d", 100000000+i)
		order.rows = append(order.rows, []any{i, inc, state, statuses[state], storeID, custID, email, fn, ln, guest,
			num(fmt.Sprintf("%.4f", grand)), num(fmt.Sprintf("%.4f", subtotal)), shipping, num(fmt.Sprintf("%.4f", tax)), num(fmt.Sprintf("%.4f", discount)),
			num(fmt.Sprintf("%.4f", qtyTotal)), weight, "EUR", coupon, ip, note, extra, payload,
			ts(created), ts(created.Add(time.Duration(r.IntN(200)) * time.Hour))})
		grid.rows = append(grid.rows, []any{i, inc, statuses[state], storeID, custID, email, fn + " " + ln, num(fmt.Sprintf("%.4f", grand)), payments[r.IntN(len(payments))], ts(created)})

		histID++
		hist.rows = append(hist.rows, []any{histID, i, true, nil, "pending", "order", ts(created)})
		if state != "new" {
			histID++
			var comment any = "Captured amount of €" + fmt.Sprintf("%.2f", grand) + " online."
			if r.IntN(3) == 0 {
				comment = nil
			}
			hist.rows = append(hist.rows, []any{histID, i, r.IntN(2) == 0, comment, statuses[state], "invoice", ts(created.Add(time.Hour))})
		}
		if r.IntN(4) > 0 {
			amID++
			amasty.rows = append(amasty.rows, []any{amID, i, 1})
		}

		// stats for postgres reporting schema
		dk := created.Format("2006-01-02")
		d := ds.stats.daily[dk]
		ds.stats.daily[dk] = [2]float64{d[0] + 1, d[1] + grand}
		if id, ok := custID.(int); ok {
			cs := ds.stats.cust[id]
			if cs == nil {
				cs = &custStat{first: created, last: created}
				ds.stats.cust[id] = cs
			}
			cs.orders++
			cs.ltv += grand
			if created.Before(cs.first) {
				cs.first = created
			}
			if created.After(cs.last) {
				cs.last = created
			}
		}
	}

	// quote
	quote := &table{name: "quote", core: true, cols: []col{
		{name: "entity_id", typ: "pk"}, {name: "store_id", typ: "ref"}, {name: "customer_id", typ: "ref", nullable: true},
		{name: "customer_email", typ: "str:255", nullable: true}, {name: "items_count", typ: "int", def: "0"},
		{name: "grand_total", typ: "dec", def: "0"}, {name: "is_active", typ: "bool"}, {name: "reserved_order_id", typ: "str:64", nullable: true},
		{name: "created_at", typ: "datetime"}, {name: "updated_at", typ: "datetime", nullable: true},
	}, indexes: [][]string{{"customer_id", "store_id", "is_active"}}}
	for i := 1; i <= 800; i++ {
		var cid, email any
		if r.IntN(3) > 0 {
			ci := r.IntN(len(people))
			cid, email = ci+1, people[ci].email
		}
		g, _ := money(0, 1200)
		created := randTime()
		var upd any
		if r.IntN(2) == 0 {
			upd = ts(created.Add(30 * time.Minute))
		}
		quote.rows = append(quote.rows, []any{i, 1 + r.IntN(3), cid, email, r.IntN(6), g, r.IntN(3) == 0, nil, ts(created), upd})
		if r.IntN(5) == 0 {
			amID++
			amasty.rows = append(amasty.rows, []any{amID, i, 2})
		}
	}

	// newsletter_subscriber
	news := &table{name: "newsletter_subscriber", core: true, cols: []col{
		{name: "subscriber_id", typ: "pk"}, {name: "store_id", typ: "ref", nullable: true}, {name: "customer_id", typ: "ref", def: "0"},
		{name: "subscriber_email", typ: "str:150", nullable: true}, {name: "subscriber_status", typ: "int", def: "0"},
		{name: "change_status_at", typ: "datetime", nullable: true},
	}, indexes: [][]string{{"subscriber_email"}}}
	for i := 1; i <= 300; i++ {
		ci := r.IntN(len(people))
		var changed any
		if r.IntN(2) == 0 {
			changed = ts(randTime())
		}
		news.rows = append(news.rows, []any{i, 1 + r.IntN(3), ci + 1, people[ci].email, 1 + r.IntN(4), changed})
	}

	// core_config_data
	ccd := &table{name: "core_config_data", core: true, cols: []col{
		{name: "config_id", typ: "pk"}, {name: "scope", typ: "str:8", def: "'default'"}, {name: "scope_id", typ: "int", def: "0"},
		{name: "path", typ: "str:255", def: "'general'"}, {name: "value", typ: "text", nullable: true},
		{name: "updated_at", typ: "datetime"},
	}, uniques: [][]string{{"scope", "scope_id", "path"}}}
	paths := []string{"web/secure/base_url", "web/unsecure/base_url", "web/seo/use_rewrites", "general/locale/code", "general/country/default",
		"currency/options/base", "currency/options/default", "catalog/search/engine", "dev/js/merge_files", "dev/css/minify_files",
		"payment/checkmo/active", "payment/ideal/active", "carriers/flatrate/price", "carriers/freeshipping/free_shipping_subtotal",
		"sales_email/order/enabled", "customer/create_account/confirm", "admin/security/session_lifetime", "cms/wysiwyg/enabled",
		"amasty_orderattr/general/enabled", "google/analytics/active", "trans_email/ident_general/email", "design/head/default_title",
		"catalog/seo/product_url_suffix", "tax/calculation/price_includes_tax", "checkout/options/guest_checkout"}
	cid := 0
	for _, p := range paths {
		for _, sc := range []struct {
			scope string
			id    int
		}{{"default", 0}, {"websites", 1}, {"stores", 1}, {"stores", 2}, {"stores", 3}} {
			if sc.scope != "default" && r.IntN(3) > 0 {
				continue
			}
			cid++
			var v any = []string{"1", "0", "https://shop.test/", "nl_NL", "EUR", "opensearch", "6.95", "Sanitairkamer"}[r.IntN(8)]
			if r.IntN(15) == 0 {
				v = nil
			}
			ccd.rows = append(ccd.rows, []any{cid, sc.scope, sc.id, p, v, ts(randTime())})
		}
	}

	// admin_user
	admin := &table{name: "admin_user", core: true, cols: []col{
		{name: "user_id", typ: "pk"}, {name: "firstname", typ: "str:32", nullable: true}, {name: "lastname", typ: "str:32", nullable: true},
		{name: "email", typ: "str:128", nullable: true}, {name: "username", typ: "str:40"}, {name: "password", typ: "str:255"},
		{name: "created", typ: "datetime"}, {name: "modified", typ: "datetime", nullable: true}, {name: "logdate", typ: "datetime", nullable: true},
		{name: "lognum", typ: "smallint", def: "0"}, {name: "is_active", typ: "bool"}, {name: "extra", typ: "text", nullable: true},
	}, uniques: [][]string{{"username"}}}
	for i, u := range [][3]string{{"Arno", "Admin", "admin"}, {"Sanne", "Support", "support"}, {"Piet", "Dev", "dev"}, {"Emma", "Marketing", "marketing"}, {"Old", "Account", "old"}} {
		var logdate any
		if i < 4 {
			logdate = ts(randTime())
		}
		admin.rows = append(admin.rows, []any{i + 1, u[0], u[1], u[2] + "@shop.test", u[2],
			"$argon2id$v=19$m=65536,t=4,p=1$" + hex.EncodeToString([]byte(u[2]+"salt")), ts(base), nil, logdate, r.IntN(400), i < 4, nil})
	}

	// catalog_category_product: composite PK
	ccp := &table{name: "catalog_category_product", core: true, cols: []col{
		{name: "category_id", typ: "ref"}, {name: "product_id", typ: "ref"}, {name: "position", typ: "int", def: "0"},
	}, pk: []string{"category_id", "product_id"},
		fks: []fk{{cols: []string{"product_id"}, refTable: "catalog_product_entity", refCols: []string{"entity_id"}}}}
	for cat := 3; cat <= 30; cat++ {
		seen := map[int]bool{}
		for k := 0; k < 32; k++ {
			p := 1 + r.IntN(300)
			if seen[p] {
				continue
			}
			seen[p] = true
			ccp.rows = append(ccp.rows, []any{cat, p, k})
		}
	}
	sort.Slice(ccp.rows, func(a, b int) bool {
		if ccp.rows[a][0].(int) != ccp.rows[b][0].(int) {
			return ccp.rows[a][0].(int) < ccp.rows[b][0].(int)
		}
		return ccp.rows[a][1].(int) < ccp.rows[b][1].(int)
	})

	// customer_visitor_log: no primary key
	vis := &table{name: "customer_visitor_log", core: true, noPK: true, cols: []col{
		{name: "visitor_id", typ: "int"}, {name: "customer_id", typ: "int", nullable: true}, {name: "session_id", typ: "str:64", nullable: true},
		{name: "last_visit_at", typ: "datetime"},
	}, indexes: [][]string{{"customer_id"}}}
	for i := 1; i <= 400; i++ {
		var c any
		if r.IntN(2) == 0 {
			c = 1 + r.IntN(600)
		}
		sess := make([]byte, 16)
		for k := range sess {
			sess[k] = byte(r.IntN(256))
		}
		// deliberate duplicate rows (no PK)
		vis.rows = append(vis.rows, []any{1000 + i%350, c, hex.EncodeToString(sess), ts(randTime())})
	}

	ds.tables = []*table{store, cust, prod, pvar, order, item, hist, grid, amasty, quote, news, ccd, admin, ccp, vis}
	ds.tables = append(ds.tables, fillers(r)...)
	return ds
}

func asciiOnly(s string) string {
	repl := strings.NewReplacer("é", "e", "ë", "e", "ü", "u", "ö", "o", "å", "a", "Å", "A", "ø", "o", "Ø", "O", "ı", "i", "'", "", "Z", "Z")
	return repl.Replace(s)
}

// fillers creates ~250 small tables so the sidebar looks like a real Magento database.
func fillers(r *rand.Rand) []*table {
	prefixes := []string{"amasty_", "mageplaza_", "mst_", "catalog_", "catalogrule_", "catalogsearch_", "cms_", "cron_", "customer_", "eav_",
		"inventory_", "klarna_", "paypal_", "quote_", "review_", "sales_", "salesrule_", "search_", "url_", "vertex_", "yotpo_", "mollie_",
		"magento_", "integration_", "oauth_", "email_", "newsletter_", "wishlist_", "tax_", "shipping_", "widget_", "admin_", "queue_", "store_"}
	middles := []string{"", "order_", "product_", "customer_", "rule_", "attribute_", "label_", "index_", "report_", "import_", "export_", "price_", "stock_"}
	suffixes := []string{"entity", "log", "queue", "grid", "store", "website", "option", "history", "tmp", "idx", "replica", "link", "value", "config", "map", "event", "item", "relation", "cl", "status"}
	core := map[string]bool{"store": true, "customer_entity": true, "catalog_product_entity": true, "catalog_product_entity_varchar": true, "sales_order": true,
		"sales_order_item": true, "sales_order_status_history": true, "sales_order_grid": true, "amasty_order_attribute_entity": true, "quote": true,
		"newsletter_subscriber": true, "core_config_data": true, "admin_user": true, "catalog_category_product": true, "customer_visitor_log": true}
	var names []string
	seen := map[string]bool{}
	for len(names) < 250 {
		n := prefixes[r.IntN(len(prefixes))] + middles[r.IntN(len(middles))] + suffixes[r.IntN(len(suffixes))]
		if seen[n] || core[n] {
			continue
		}
		seen[n] = true
		names = append(names, n)
	}
	sort.Strings(names)
	pool := []col{
		{name: "customer_email", typ: "str:255", nullable: true}, {name: "store_id", typ: "ref", nullable: true},
		{name: "status", typ: "str:32"}, {name: "sku", typ: "str:64", nullable: true}, {name: "value", typ: "text", nullable: true},
		{name: "entity_id", typ: "int"}, {name: "product_id", typ: "int", nullable: true}, {name: "name", typ: "str:255"},
		{name: "is_active", typ: "bool"}, {name: "sort_order", typ: "int", def: "0"}, {name: "code", typ: "str:64"},
		{name: "payload", typ: "json", nullable: true}, {name: "amount", typ: "dec", nullable: true}, {name: "order_id", typ: "int", nullable: true},
	}
	var out []*table
	for _, n := range names {
		t := &table{name: n, cols: []col{{name: "id", typ: "pk"}}}
		picked := map[int]bool{}
		for k := 0; k < 2+r.IntN(4); k++ {
			picked[r.IntN(len(pool))] = true
		}
		var idx []int
		for k := range picked {
			idx = append(idx, k)
		}
		sort.Ints(idx)
		for _, k := range idx {
			t.cols = append(t.cols, pool[k])
		}
		t.cols = append(t.cols, col{name: "created_at", typ: "datetime"})
		nRows := r.IntN(16)
		for i := 1; i <= nRows; i++ {
			row := []any{i}
			for _, c := range t.cols[1:] {
				row = append(row, fillerValue(r, c, i))
			}
			t.rows = append(t.rows, row)
		}
		out = append(out, t)
	}
	return out
}

func fillerValue(r *rand.Rand, c col, i int) any {
	if c.nullable && r.IntN(4) == 0 {
		return nil
	}
	switch c.name {
	case "customer_email":
		return fmt.Sprintf("%s%d@%s", strings.ToLower(asciiOnly(firstNames[r.IntN(len(firstNames))])), i, domains[r.IntN(len(domains))])
	case "store_id":
		return 1 + r.IntN(3)
	case "status":
		return []string{"pending", "done", "error", "running"}[r.IntN(4)]
	case "sku":
		return fmt.Sprintf("SKU-%05d", 10000+r.IntN(300)*7)
	case "value":
		return fmt.Sprintf("value %d", r.IntN(1000))
	case "entity_id", "order_id":
		return 1 + r.IntN(2000)
	case "product_id":
		return 1 + r.IntN(300)
	case "name":
		return productAdj[r.IntN(len(productAdj))] + " " + productN[r.IntN(len(productN))]
	case "is_active":
		return r.IntN(2) == 0
	case "sort_order":
		return r.IntN(100)
	case "code":
		return fmt.Sprintf("code_%d", i)
	case "payload":
		return fmt.Sprintf(`{"n": %d}`, r.IntN(100))
	case "amount":
		return num(fmt.Sprintf("%.4f", r.Float64()*500))
	case "created_at":
		return ts(time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC).Add(time.Duration(r.IntN(500*24)) * time.Hour))
	}
	return nil
}

func (d dialect) viewSQL(schema string) string {
	pre := ""
	if schema != "" {
		pre = d.q(schema) + "."
	}
	return fmt.Sprintf(`CREATE VIEW %ssales_order_summary_view AS
SELECT o.entity_id, o.increment_id, o.status, o.grand_total, o.customer_email, s.code AS store_code,
       (SELECT COUNT(*) FROM %ssales_order_item i WHERE i.order_id = o.entity_id) AS item_count, o.created_at
FROM %ssales_order o
JOIN %sstore s ON s.store_id = o.store_id`, pre, pre, pre, pre)
}

// ---------------------------------------------------------------------------
// Engines

func execAll(db *sql.DB, stmts []string) error {
	for _, s := range stmts {
		if _, err := db.Exec(s); err != nil {
			short := s
			if len(short) > 300 {
				short = short[:300] + "..."
			}
			return fmt.Errorf("%w\n-- statement:\n%s", err, short)
		}
	}
	return nil
}

func build(d dialect, ds *dataset, schema string, withFillers bool) []string {
	var stmts []string
	for _, t := range ds.tables {
		if !t.core && !withFillers {
			continue
		}
		stmts = append(stmts, d.createTable(t, schema)...)
	}
	for _, t := range ds.tables {
		if !t.core && !withFillers {
			continue
		}
		stmts = append(stmts, d.inserts(t, schema, 250)...)
	}
	stmts = append(stmts, d.viewSQL(schema))
	return stmts
}

func seedMySQL(dbName string, ds *dataset, withFillers bool) error {
	if !allowedMySQL[dbName] {
		return fmt.Errorf("refusing to touch MySQL database %q", dbName)
	}
	start := time.Now()
	admin, err := sql.Open("mysql", "root@unix("+mysqlSocket+")/")
	if err != nil {
		return err
	}
	defer admin.Close()
	if err := execAll(admin, []string{
		"DROP DATABASE IF EXISTS `" + dbName + "`",
		"CREATE DATABASE `" + dbName + "` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci",
	}); err != nil {
		return err
	}
	db, err := sql.Open("mysql", "root@unix("+mysqlSocket+")/"+dbName+"?charset=utf8mb4")
	if err != nil {
		return err
	}
	defer db.Close()
	db.SetMaxOpenConns(1)
	stmts := append([]string{"SET SESSION sql_mode = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION'"}, build(dMySQL, ds, "", withFillers)...)
	if err := execAll(db, stmts); err != nil {
		return fmt.Errorf("mysql %s: %w", dbName, err)
	}
	return report("mysql "+dbName, db, "SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = DATABASE()", dMySQL, "", start)
}

func seedPostgres(ds *dataset) error {
	start := time.Now()
	admin, err := sql.Open("pgx", pgAdminDSN)
	if err != nil {
		return err
	}
	defer admin.Close()
	if err := execAll(admin, []string{
		"DROP DATABASE IF EXISTS dbviewer_dummy WITH (FORCE)",
		"CREATE DATABASE dbviewer_dummy",
	}); err != nil {
		return err
	}
	db, err := sql.Open("pgx", pgDummyDSN)
	if err != nil {
		return err
	}
	defer db.Close()
	stmts := build(dPG, ds, "", true)
	// resync identity sequences after explicit ids
	for _, t := range ds.tables {
		for _, c := range t.cols {
			if c.typ == "pk" && len(t.rows) > 0 {
				stmts = append(stmts, fmt.Sprintf(`SELECT setval(pg_get_serial_sequence('%s', '%s'), (SELECT MAX("%s") FROM "%s"))`, t.name, c.name, c.name, t.name))
			}
		}
	}
	stmts = append(stmts, `COMMENT ON TABLE sales_order IS 'Orders (Magento-like dummy data)'`,
		`COMMENT ON COLUMN sales_order.extra_data IS 'Arbitrary JSON metadata'`)

	// reporting schema
	stmts = append(stmts, `CREATE SCHEMA reporting`,
		`CREATE TABLE reporting.daily_sales (
  day date PRIMARY KEY,
  orders integer NOT NULL,
  revenue numeric(20,4) NOT NULL,
  avg_order numeric(20,4) NOT NULL
)`,
		`CREATE TABLE reporting.customer_ltv (
  customer_id integer PRIMARY KEY REFERENCES public.customer_entity (entity_id) ON DELETE CASCADE,
  orders integer NOT NULL,
  ltv numeric(20,4) NOT NULL,
  first_order_at timestamp NOT NULL,
  last_order_at timestamp NOT NULL,
  customer_email varchar(255)
)`,
		`CREATE TABLE reporting.export_log (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  run_at timestamptz NOT NULL DEFAULT now(),
  kind text NOT NULL,
  rows_written integer,
  meta jsonb,
  tags text[],
  run_id uuid
)`)
	days := make([]string, 0, len(ds.stats.daily))
	for k := range ds.stats.daily {
		days = append(days, k)
	}
	sort.Strings(days)
	var rows []string
	for _, k := range days {
		v := ds.stats.daily[k]
		rows = append(rows, fmt.Sprintf("('%s', %d, %.4f, %.4f)", k, int(v[0]), v[1], v[1]/v[0]))
	}
	for i := 0; i < len(rows); i += 300 {
		stmts = append(stmts, "INSERT INTO reporting.daily_sales VALUES\n"+strings.Join(rows[i:min(i+300, len(rows))], ",\n"))
	}
	ids := make([]int, 0, len(ds.stats.cust))
	for id := range ds.stats.cust {
		ids = append(ids, id)
	}
	sort.Ints(ids)
	rows = rows[:0]
	for _, id := range ids {
		c := ds.stats.cust[id]
		rows = append(rows, fmt.Sprintf("(%d, %d, %.4f, '%s', '%s', (SELECT email FROM public.customer_entity WHERE entity_id = %d))",
			id, c.orders, c.ltv, c.first.Format("2006-01-02 15:04:05"), c.last.Format("2006-01-02 15:04:05"), id))
	}
	for i := 0; i < len(rows); i += 300 {
		stmts = append(stmts, "INSERT INTO reporting.customer_ltv VALUES\n"+strings.Join(rows[i:min(i+300, len(rows))], ",\n"))
	}
	stmts = append(stmts,
		`INSERT INTO reporting.export_log (run_at, kind, rows_written, meta, tags, run_id)
SELECT now() - (g || ' hours')::interval, (ARRAY['csv','json','sql'])[1 + g % 3], CASE WHEN g % 7 = 0 THEN NULL ELSE g * 13 END,
       jsonb_build_object('g', g, 'ok', g % 5 <> 0), ARRAY['nightly', 'g' || g], md5(g::text)::uuid
FROM generate_series(1, 120) g`,
		`CREATE VIEW reporting.v_top_customers AS
SELECT l.customer_id, c.firstname, c.lastname, l.customer_email, l.orders, l.ltv
FROM reporting.customer_ltv l JOIN public.customer_entity c ON c.entity_id = l.customer_id
ORDER BY l.ltv DESC LIMIT 100`,
		`CREATE MATERIALIZED VIEW reporting.mv_monthly_sales AS
SELECT date_trunc('month', day)::date AS month, SUM(orders) AS orders, SUM(revenue) AS revenue
FROM reporting.daily_sales GROUP BY 1`,
		`ANALYZE`)
	if err := execAll(db, stmts); err != nil {
		return fmt.Errorf("postgres: %w", err)
	}
	return report("postgres dbviewer_dummy", db, "SELECT COUNT(*) FROM information_schema.tables WHERE table_schema IN ('public','reporting')", dPG, "", start)
}

func removeSQLite(path string) error {
	for _, p := range []string{path, path + "-wal", path + "-shm", path + "-journal"} {
		if err := os.Remove(p); err != nil && !os.IsNotExist(err) {
			return err
		}
	}
	return nil
}

func seedSQLite(path string, ds *dataset) error {
	start := time.Now()
	if base := filepath.Base(path); base != "dummy.sqlite" {
		return fmt.Errorf("refusing to write %s", path)
	}
	if err := removeSQLite(path); err != nil {
		return err
	}
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return err
	}
	defer db.Close()
	db.SetMaxOpenConns(1)
	stmts := append([]string{"PRAGMA foreign_keys = ON", "BEGIN"}, build(dSQLite, ds, "", true)...)
	stmts = append(stmts, "COMMIT", "ANALYZE")
	if err := execAll(db, stmts); err != nil {
		return fmt.Errorf("sqlite: %w", err)
	}
	return report("sqlite "+path, db, "SELECT COUNT(*) FROM sqlite_master WHERE type IN ('table','view') AND name NOT LIKE 'sqlite_%'", dSQLite, "", start)
}

func seedCache(path string) error {
	if filepath.Base(path) != "cache.sqlite" {
		return fmt.Errorf("refusing to write %s", path)
	}
	if err := removeSQLite(path); err != nil {
		return err
	}
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return err
	}
	defer db.Close()
	db.SetMaxOpenConns(1)
	stmts := []string{
		"BEGIN",
		`CREATE TABLE kv_cache (key TEXT PRIMARY KEY, value TEXT, expires_at DATETIME)`,
		`CREATE TABLE http_cache (url TEXT PRIMARY KEY, status INTEGER NOT NULL, etag TEXT, body BLOB, fetched_at DATETIME NOT NULL)`,
		`CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id INTEGER, payload JSON, last_seen DATETIME)`,
		`WITH RECURSIVE g(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM g WHERE n < 500)
INSERT INTO kv_cache SELECT 'key:' || n, CASE WHEN n % 9 = 0 THEN NULL ELSE 'value ' || n END, datetime('2026-01-01', '+' || n || ' minutes') FROM g`,
		`WITH RECURSIVE g(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM g WHERE n < 200)
INSERT INTO http_cache SELECT 'https://api.example.test/v1/items/' || n, CASE WHEN n % 13 = 0 THEN 404 ELSE 200 END, hex(randomblob(8)), randomblob(32), datetime('2026-01-01', '+' || n || ' hours') FROM g`,
		`WITH RECURSIVE g(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM g WHERE n < 150)
INSERT INTO sessions SELECT lower(hex(randomblob(16))), CASE WHEN n % 4 = 0 THEN NULL ELSE n END, json_object('cart', n % 5, 'locale', 'nl_NL'), datetime('2026-01-01', '+' || n || ' minutes') FROM g`,
		"COMMIT",
	}
	if err := execAll(db, stmts); err != nil {
		return fmt.Errorf("sqlite cache: %w", err)
	}
	var n int
	_ = db.QueryRow("SELECT (SELECT COUNT(*) FROM kv_cache) + (SELECT COUNT(*) FROM http_cache) + (SELECT COUNT(*) FROM sessions)").Scan(&n)
	fmt.Printf("%-34s 3 tables, %d rows\n", "sqlite "+path, n)
	return nil
}

func report(label string, db *sql.DB, tableCountSQL string, d dialect, schema string, start time.Time) error {
	var tables int
	if err := db.QueryRow(tableCountSQL).Scan(&tables); err != nil {
		return err
	}
	var parts []string
	for _, t := range []string{"sales_order", "sales_order_item", "customer_entity", "catalog_product_entity", "customer_visitor_log", "sales_order_summary_view"} {
		var n int
		if err := db.QueryRow("SELECT COUNT(*) FROM " + d.q(t)).Scan(&n); err != nil {
			return err
		}
		parts = append(parts, fmt.Sprintf("%s=%d", t, n))
	}
	fmt.Printf("%-34s %d tables+views (%s) in %s\n", label, tables, strings.Join(parts, " "), time.Since(start).Round(time.Millisecond))
	return nil
}

// seedAppData creates the dev app-state dir (testdata/appdata) with two projects and
// five connections to the dummy databases. Existing app data is left alone.
func seedAppData(dir string) error {
	appdir := filepath.Join(dir, "appdata")
	if _, err := os.Stat(filepath.Join(appdir, "state.sqlite")); err == nil {
		fmt.Printf("%-34s exists, left alone\n", appdir)
		return nil
	}
	st, err := store.Open(appdir)
	if err != nil {
		return err
	}
	defer st.Close()
	ps, err := st.Projects()
	if err != nil {
		return err
	}
	shop := ps[0]
	shop.Name = "Dummy shop"
	if shop, err = st.SaveProject(shop); err != nil {
		return err
	}
	other, err := st.SaveProject(model.Project{Name: "Other project"})
	if err != nil {
		return err
	}
	abs, _ := filepath.Abs(dir)
	empty, pgpw := "", "dbviewer"
	for _, c := range []model.ConnectionConfig{
		{ProjectID: shop.ID, Name: "dummy (local mysql)", Driver: model.DriverMySQL, Socket: mysqlSocket, User: "root", Password: &empty, Database: "dbviewer_dummy", Color: model.ColorGreen},
		{ProjectID: shop.ID, Name: "dummy_ro (production)", Driver: model.DriverMySQL, Socket: mysqlSocket, User: "root", Database: "dbviewer_dummy_ro", Color: model.ColorRed, ReadOnly: true},
		{ProjectID: shop.ID, Name: "dummy (postgres)", Driver: model.DriverPostgres, Host: "127.0.0.1", Port: 55432, User: "postgres", Password: &pgpw, Database: "dbviewer_dummy", SSLMode: model.SSLDisable, Color: model.ColorBlue},
		{ProjectID: shop.ID, Name: "dummy.sqlite", Driver: model.DriverSQLite, FilePath: filepath.Join(abs, "dummy.sqlite")},
		{ProjectID: other.ID, Name: "cache.sqlite", Driver: model.DriverSQLite, FilePath: filepath.Join(abs, "cache.sqlite"), Color: model.ColorPurple},
	} {
		if _, err := st.SaveConnection(c); err != nil {
			return err
		}
	}
	fmt.Printf("%-34s 2 projects, 5 connections\n", appdir)
	return nil
}
